namespace Bancoficticio.Transferencias.Tests;

public sealed class RealizarTransferenciaServiceTests
{
    // ---------------------------------------------------------------- fakes

    private sealed class FakeCuentas(List<string> events) : CuentaRepository
    {
        public Dictionary<string, Cuenta> Cuentas { get; } = new();
        public List<string?> FindCalls { get; } = new();
        public List<string?> ExistsActiveCalls { get; } = new();
        public List<(string? Cuenta, decimal? Valor)> Debits { get; } = new();
        public List<(string? Cuenta, decimal? Valor)> Credits { get; } = new();

        public void Add(string numero, string estado, decimal saldo) =>
            Cuentas[numero] = new Cuenta(numero, estado, saldo);

        public Cuenta? FindByNumero(string? cuenta)
        {
            events.Add("cuentas.findByNumero");
            FindCalls.Add(cuenta);
            return cuenta != null && Cuentas.TryGetValue(cuenta, out var c) ? c : null;
        }

        public bool ExistsActive(string? cuenta)
        {
            events.Add("cuentas.existsActive");
            ExistsActiveCalls.Add(cuenta);
            return cuenta != null && Cuentas.TryGetValue(cuenta, out var c) && c.Estado == "A";
        }

        public void Debit(string? cuenta, decimal? valor)
        {
            events.Add("cuentas.debit");
            Debits.Add((cuenta, valor));
            if (cuenta != null && Cuentas.TryGetValue(cuenta, out var c))
                Cuentas[cuenta] = c with { Saldo = c.Saldo - valor };
        }

        public void Credit(string? cuenta, decimal? valor)
        {
            events.Add("cuentas.credit");
            Credits.Add((cuenta, valor));
            if (cuenta != null && Cuentas.TryGetValue(cuenta, out var c))
                Cuentas[cuenta] = c with { Saldo = c.Saldo + valor };
        }
    }

    private sealed class FakeTransferencias(List<string> events) : TransferenciaRepository
    {
        public int Next { get; set; } = 1;
        public int NextNumeroCalls { get; private set; }
        public List<Transferencia> Registered { get; } = new();

        public int NextNumero()
        {
            events.Add("transferencias.nextNumero");
            NextNumeroCalls++;
            return Next;
        }

        public void Register(int? numero, string? origen, string? destino, decimal? monto, decimal? comision, string? tipo)
        {
            events.Add("transferencias.register");
            Registered.Add(new Transferencia(numero, origen, destino, monto, comision, tipo));
        }

        public Transferencia? FindByNumero(int? numero)
        {
            events.Add("transferencias.findByNumero");
            return null;
        }
    }

    private sealed class FakeUnitOfWork(List<string> events) : UnitOfWork
    {
        public void Begin() => events.Add("uow.begin");
        public void Commit() => events.Add("uow.commit");
        public void Rollback() => events.Add("uow.rollback");
    }

    private sealed class Harness
    {
        public List<string> Events { get; } = new();
        public FakeCuentas Cuentas { get; }
        public FakeTransferencias Transferencias { get; }
        public FakeUnitOfWork Uow { get; }
        public RealizarTransferenciaService Service { get; }

        public Harness()
        {
            Cuentas = new FakeCuentas(Events);
            Transferencias = new FakeTransferencias(Events);
            Uow = new FakeUnitOfWork(Events);
            Service = new RealizarTransferenciaService(Cuentas, Transferencias, Uow);
        }
    }

    private static Harness Prepared(decimal saldoOrigen, decimal saldoDestino = 50.00m)
    {
        var h = new Harness();
        h.Cuentas.Add("1001", "A", saldoOrigen);
        h.Cuentas.Add("2002", "A", saldoDestino);
        return h;
    }

    private static RealizarTransferenciaResponse Run(Harness h, string? origen, string? destino, decimal? monto, string? tipo) =>
        h.Service.Execute(new RealizarTransferenciaRequest(origen, destino, monto, tipo));

    private static void AssertRejected(RealizarTransferenciaResponse r, string mensaje)
    {
        Assert.Equal((int?)-1, r.Status);
        Assert.Equal(mensaje, r.Mensaje);
    }

    private static void AssertNothingWritten(Harness h)
    {
        Assert.Empty(h.Cuentas.Debits);
        Assert.Empty(h.Cuentas.Credits);
        Assert.Empty(h.Transferencias.Registered);
        Assert.Equal(0, h.Transferencias.NextNumeroCalls);
        Assert.DoesNotContain("uow.commit", h.Events);
    }

    // ------------------------------------------------- RULE-005 same account

    [Fact]
    public void Rule005_SameAccount_RejectedWithoutAnyDatabaseAccess()
    {
        var h = Prepared(1000m);

        var r = Run(h, "1001", "1001", 100m, "TRF");

        AssertRejected(r, "LA CUENTA DESTINO ES LA MISMA");
        Assert.Empty(h.Events); // no begin, no reads, no rollback
    }

    [Fact]
    public void Rule005_SameAccountAfterTrimmingWhitespace_Rejected()
    {
        var h = Prepared(1000m);

        var r = Run(h, " 1001 ", "1001", 100m, "TRF");

        AssertRejected(r, "LA CUENTA DESTINO ES LA MISMA");
        Assert.Empty(h.Events);
    }

    [Fact]
    public void Rule005_SameAccountTrailingWhitespaceOnDestination_Rejected()
    {
        var h = Prepared(1000m);

        var r = Run(h, "1001", "  1001", 100m, "TRF");

        AssertRejected(r, "LA CUENTA DESTINO ES LA MISMA");
        Assert.Empty(h.Events);
    }

    [Fact]
    public void Rule005_SameAccountCheckIsCaseSensitive_DifferentCaseIsNotTheSameAccount()
    {
        var h = new Harness();
        h.Cuentas.Add("AB1", "A", 1000m);
        h.Cuentas.Add("ab1", "A", 10m);

