using Bancoficticio.Transferencias.Domain.Port;
using Bancoficticio.Transferencias.Infrastructure;

namespace Bancoficticio.Transferencias.Adapters.Out.Sql;

/// <summary>ADO.NET adapter of the UnitOfWork port: delegates to the transaction held by Db.
/// The platform opens one transaction per request (or golden case) on the shared connection; SqlClient
/// does not allow a second one, so Begin only opens a transaction when Db has none, and Commit and
/// Rollback only act on a transaction opened here. Otherwise the platform's transaction is the unit of
/// work: it confirms it at the end of the request, and a rejection returns before any write.</summary>
public sealed class SqlUnitOfWork(Db db) : UnitOfWork
{
    private bool _owns;

    public void Begin()
    {
        if (db.Transaction == null)
        {
            db.Begin();
            _owns = true;
        }
    }

    public void Commit()
    {
        if (_owns)
        {
            db.Commit();
            _owns = false;
        }
    }

    public void Rollback()
    {
        if (_owns)
        {
            db.Rollback();
            _owns = false;
        }
    }
}
